'use strict';
/* 용병·보스 그림 (img 폴더 없이도 뜨도록 파일 하나에 담았어요) */
const IMGDATA = {"blade_0":"","blade_1":"","blade_2":"","chrono_0":"","chrono_1":"","chrono_2":"","codeh_0":"","codeh_1":"","eclipse_0":"","eclipse_1":"","eclipse_2":"","glitch_0":"","glitch_1":"","glitch_2":"","halo_0":"","halo_1":"","halo_2":"","hawkeye_0":"","hawkeye_1":"","hawkeye_2":"","ironwall_0":"","ironwall_1":"","ironwall_2":"","nano_0":"","nano_1":"","nano_2":"","neuro_0":"","neuro_1":"","neuro_2":"","pug_0":"","pug_1":"","pug_2":"","reaper_0":"","reaper_1":"","reaper_2":"","specter_0":"","specter_1":"","specter_2":"","swarm_0":"","swarm_1":"","swarm_2":"","volt_0":"","volt_1":"","volt_2":"","codeh_2":""};

/*ATK*/Object.assign(IMGDATA, {"blade_a0":"","blade_a1":"","blade_a2":"","chrono_a0":"","chrono_a1":"","chrono_a2":"","eclipse_a0":"","eclipse_a1":"","eclipse_a2":"","halo_a0":"","halo_a1":"","halo_a2":"","volt_a0":"","volt_a1":"","volt_a2":"","nano_a0":"","nano_a1":"","nano_a2":"","neuro_a0":"","neuro_a1":"","neuro_a2":"","glitch_a0":"","glitch_a1":"","glitch_a2":"","specter_a0":"","specter_a1":"","specter_a2":"","hawkeye_a0":"","hawkeye_a1":"","hawkeye_a2":"","reaper_a0":"","reaper_a1":"","reaper_a2":"","pug_a0":"","pug_a1":"","pug_a2":"","ironwall_a0":"","ironwall_a1":"","ironwall_a2":"","codeh_a0":"","codeh_a1":"","swarm_a0":"","swarm_a1":"","swarm_a2":""});/*ATK*/
const IMGURL = {};
(function () {
  for (const k in IMGDATA) {
    try {
      const bin = atob(IMGDATA[k]), u = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
      IMGURL[k] = URL.createObjectURL(new Blob([u], { type: 'image/webp' }));
    } catch (e) { IMGURL[k] = 'data:image/webp;base64,' + IMGDATA[k]; }
  }
})();
/* 그림이 아직 없는 보스는 art 용병 그림을 빌려 써요 */
for (const b in (typeof BOSSES !== 'undefined' ? BOSSES : {})) for (let f = 0; f < 3; f++) if (!IMGURL[`${b}_${f}`]) IMGURL[`${b}_${f}`] = IMGURL[`${BOSSES[b].art}_${Math.min(2, f + 1)}`];
